if(s==="\u0cb5\u0cc8\u0cb6\u0cbe\u0c96")if(r===2)k.push(new A.bP("\u0c85\u0c95\u0ccd\u0cb7\u0caf \u0ca4\u0cc3\u0ca4\u0cc0\u0caf\u0cbe","\u0c85\u0ca4\u0ccd\u0caf\u0c82\u0ca4 \u0cb6\u0cc1\u0cad\u0ca6\u0cbf\u0ca8. \u0c87\u0c82\u0ca6\u0cc1 \u0cae\u0cbe\u0ca1\u0cbf\u0ca6 \u0ca6\u0cbe\u0ca8, \u0c9c\u0caa\u0c97\u0cb3\u0cc1 \u0c85\u0c95\u0ccd\u0cb7\u0caf \u0cab\u0cb2 \u0ca8\u0cc0\u0ca1\u0cc1\u0ca4\u0ccd\u0ca4\u0cb5\u0cc6.","\u0cb5\u0cc8\u0cb6\u0cbe\u0c96\u0cb8\u0ccd\u0caf \u0cb8\u0cbf\u0ca4\u0cc7 \u0caa\u0c95\u0ccd\u0cb7\u0cc7 \u0ca4\u0cc3\u0ca4\u0cc0\u0caf\u0cbe\u0caf\u0cbe\u0cae\u0cc1\u0caa\u0ccb\u0cb7\u0cbf\u0ca4\u0c83 |\\n\u0c85\u0c95\u0ccd\u0cb7\u0caf\u0c82 \u0cb2\u0cad\u0ca4\u0cc7 \u0caa\u0cc1\u0ca3\u0ccd\u0caf\u0c82 \u0cb8\u0ccd\u0ca8\u0cbe\u0ca4\u0ccd\u0cb5\u0cbe \u0cad\u0c95\u0ccd\u0ca4\u0ccd\u0caf\u0cbe \u0c9c\u0ca8\u0cbe\u0cb0\u0ccd\u0ca6\u0ca8\u0cae\u0ccd ||","\u0cb5\u0cc8\u0cb6\u0cbe\u0c96 \u0cb6\u0cc1\u0c95\u0ccd\u0cb2 \u0ca4\u0cc3\u0ca4\u0cc0\u0caf\u0cbe \u0c85\u0cad\u0cc1\u0ca6\u0caf \u0ca4\u0cbf\u0ca5\u0cbf - \u0cae\u0cc1\u0cb9\u0cc2\u0cb0\u0ccd\u0ca4 \u0ca8\u0cbf\u0cb0\u0ccd\u0ca3\u0caf \u0cac\u0cc7\u0c95\u0cbf\u0cb2\u0ccd\u0cb2. \u0cb8\u0cc2\u0cb0\u0ccd\u0caf\u0ccb\u0ca6\u0caf\u0ca6\u0cbf\u0c82\u0ca6 \u0cb8\u0cc2\u0cb0\u0ccd\u0caf\u0cbe\u0cb8\u0ccd\u0ca4\u0ca6\u0cb5\u0cb0\u0cc6\u0c97\u0cc6 \u0ca4\u0cc3\u0ca4\u0cc0\u0caf\u0cbe \u0cb5\u0ccd\u0caf\u0cbe\u0caa\u0ccd\u0ca4\u0cbf \u0c87\u0cb0\u0cac\u0cc7\u0c95\u0cc1. \u0ca6\u0cbe\u0ca8-\u0ca7\u0cb0\u0ccd\u0cae \u0c85\u0c95\u0ccd\u0cb7\u0caf \u0cab\u0cb2 \u0ca8\u0cc0\u0ca1\u0cc1\u0ca4\u0ccd\u0ca4\u0ca6\u0cc6. \u0cb5\u0cbf\u0cb7\u0ccd\u0ca3\u0cc1 \u0caa\u0cc2\u0c9c\u0cc6, \u0c89\u0caa\u0cb5\u0cbe\u0cb8 \u0cae\u0cbe\u0ca1\u0cac\u0cc7\u0c95\u0cc1.",o))
else if(r===6)k.push(new A.bP("\u0c97\u0c82\u0c97\u0ccb\u0ca4\u0ccd\u0caa\u0ca4\u0ccd\u0ca4\u0cbf / \u0c9c\u0cb9\u0ccd\u0ca8\u0cc1 \u0cb8\u0caa\u0ccd\u0ca4\u0cae\u0cbf","\u0c97\u0c82\u0c97\u0cbe\u0ca6\u0cc7\u0cb5\u0cbf\u0caf \u0c85\u0cb5\u0ca4\u0cb0\u0ca3 \u0ca6\u0cbf\u0ca8. \u0c97\u0c82\u0c97\u0cbe \u0cb8\u0ccd\u0ca8\u0cbe\u0ca8, \u0caa\u0cc2\u0c9c\u0cc6\u0c97\u0cc6 \u0cb6\u0ccd\u0cb0\u0cc7\u0cb7\u0ccd\u0ca0.","\u0cb5\u0cc8\u0cb6\u0cbe\u0c96\u0cc7 \u0cb6\u0cc1\u0c95\u0ccd\u0cb2\u0cb8\u0caa\u0ccd\u0ca4\u0cae\u0ccd\u0caf\u0cbe\u0c82 \u0c97\u0c82\u0c97\u0cbe \u0cb8\u0cbe\u0c97\u0cb0\u0cae\u0cbe\u0c97\u0ca4\u0cbe |\\n\u0ca4\u0cb8\u0ccd\u0caf\u0cbe\u0c82 \u0cb8\u0ccd\u0ca8\u0cbe\u0ca4\u0ccd\u0cb5\u0cbe \u0ca8\u0cb0\u0ccb \u0cad\u0c95\u0ccd\u0ca4\u0ccd\u0caf\u0cbe \u0cb8\u0cb0\u0ccd\u0cb5\u0caa\u0cbe\u0caa\u0cc8\u0c83 \u0caa\u0ccd\u0cb0\u0cae\u0cc1\u0c9a\u0ccd\u0caf\u0ca4\u0cc7 ||","\u0cb5\u0cc8\u0cb6\u0cbe\u0c96 \u0cb6\u0cc1\u0c95\u0ccd\u0cb2 \u0cb8\u0caa\u0ccd\u0ca4\u0cae\u0cbf \u0cb8\u0cc2\u0cb0\u0ccd\u0caf\u0ccb\u0ca6\u0caf \u0cb5\u0ccd\u0caf\u0cbe\u0caa\u0cbf\u0ca8\u0cbf \u0c86\u0c97\u0cbf\u0cb0\u0cac\u0cc7\u0c95\u0cc1. \u0ca8\u0ca6\u0cbf/\u0c9c\u0cb2\u0cbe\u0cb6\u0caf\u0ca6\u0cb2\u0ccd\u0cb2\u0cbf \u0caa\u0cc1\u0ca3\u0ccd\u0caf\u0cb8\u0ccd\u0ca8\u0cbe\u0ca8 \u0cae\u0cbe\u0ca1\u0cbf \u0c97\u0c82\u0c97\u0cbe \u0ca6\u0cc7\u0cb5\u0cbf\u0c97\u0cc6 \u0c85\u0cb0\u0ccd\u0c98\u0ccd\u0caf \u0ca8\u0cc0\u0ca1\u0cac\u0cc7\u0c95\u0cc1. \u0c9c\u0cb2\u0ca6\u0cbe\u0ca8 \u0cae\u0cbe\u0ca1\u0cac\u0cc7\u0c95\u0cc1.",n))
else if(r===10)k.push(new A.bP("\u0cae\u0ccb\u0cb9\u0cbf\u0ca8\u0cc0 \u0c8f\u0c95\u0cbe\u0ca6\u0cb6\u0cbf","\u0cae\u0cb9\u0cbe\u0cb5\u0cbf\u0cb7\u0ccd\u0ca3\u0cc1\u0cb5\u0cbf\u0ca8 \u0cae\u0ccb\u0cb9\u0cbf\u0ca8\u0cc0 \u0c85\u0cb5\u0ca4\u0cbe\u0cb0\u0ca6 \u0cb8\u0ccd\u0cae\u0cb0\u0ca3\u0cc6. \u0cb8\u0c95\u0cb2 \u0caa\u0cbe\u0caa \u0ca8\u0cbe\u0cb6\u0c95 \u0c89\u0caa\u0cb5\u0cbe\u0cb8.","\u0cb5\u0cc8\u0cb6\u0cbe\u0c96\u0cb8\u0ccd\u0caf \u0cb8\u0cbf\u0ca4\u0cc7 \u0caa\u0c95\u0ccd\u0cb7\u0cc7 \u0c8f\u0c95\u0cbe\u0ca6\u0cb6\u0ccd\u0caf\u0cbe\u0c82 \u0ca8\u0cbf\u0cb0\u0cbe\u0cae\u0cbf\u0cb7\u0cae\u0ccd |\\n\u0cae\u0ccb\u0cb9\u0cbf\u0ca8\u0cc0 \u0cb8\u0cbe \u0cb8\u0cae\u0cbe\u0c96\u0ccd\u0caf\u0cbe\u0ca4\u0cbe \u0cb8\u0cb0\u0ccd\u0cb5\u0caa\u0cbe\u0caa \u0caa\u0ccd\u0cb0\u0ca3\u0cbe\u0cb6\u0cbf\u0ca8\u0cc0 ||","\u0c8f\u0c95\u0cbe\u0ca6\u0cb6\u0cbf \u0c85\u0cb0\u0cc1\u0ca3\u0ccb\u0ca6\u0caf \u0cb5\u0ccd\u0caf\u0cbe\u0caa\u0cbf\u0ca8\u0cbf \u0c86\u0c97\u0cbf\u0cb0\u0cac\u0cc7\u0c95\u0cc1 (\u0cb8\u0cc2\u0cb0\u0ccd\u0caf\u0ccb\u0ca6\u0caf\u0c95\u0ccd\u0c95\u0cc6 \u0cef\u0cec \u0ca8\u0cbf\u0cae\u0cbf\u0cb7 \u0cae\u0cca\u0ca6\u0cb2\u0cc1). \u0ca6\u0cb6\u0cae\u0cbf \u0cb5\u0cbf\u0ca6\u0ccd\u0ca7\u0cc6 \u0c86\u0c97\u0cbf\u0cb0\u0cac\u0cbe\u0cb0\u0ca6\u0cc1. \u0cb8\u0c82\u0caa\u0cc2\u0cb0\u0ccd\u0ca3 \u0c89\u0caa\u0cb5\u0cbe\u0cb8 - \u0ca7\u0cbe\u0ca8\u0ccd\u0caf, \u0c86\u0cae\u0cbf\u0cb7 \u0ca4\u0ccd\u0caf\u0c9c\u0cbf\u0cb8\u0cac\u0cc7\u0c95\u0cc1. \u0ca6\u0ccd\u0cb5\u0cbe\u0ca6\u0cb6\u0cbf\u0caf\u0cb2\u0ccd\u0cb2\u0cbf \u0caa\u0cbe\u0cb0\u0ca3\u0cc6.",o))
